#include <bits/stdc++.h>

using namespace std;

const int N = 1e5 + 10;
string dp[N];
// dp[sum] 当前选了sum根木棍所能达到最小数字num
int f[] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};

bool cmp(string s1, string s2) { //s1>s2 true
	int len1 = s1.size(), len2 = s2.size();
	if (len1 != len2) {
		return len1 > len2;
	} else {
		for (int i = 0; i < len1; i++) {
			if (s1[i] != s2[i]) {
				return s1[i] > s2[i];
			}
		}
		return false;
	}
}

string tmp = "";

int main() {
	freopen("sticks.in", "r", stdin);
	freopen("sticks.out", "w", stdout);
	
	int t;
	scanf("%d", &t);
	while (t--) {
		int n;
		scanf("%d", &n);
		
		dp[0] = "";
		for (int i = 1; i <= n; i++) {
			dp[i] = tmp;
		}
		for (int i = 0; i <= n; i++) {
			for (int j = 0; j < 10; j++) {
				if (dp[i] == "" && j == 0) continue;
				if (i + f[j] <= n) {
		//					dp[i+f[j]] = min(dp[i+f[j]], dp[i] * 10 + j);
					string s = dp[i] + to_string(j);
					if ((!cmp(s, dp[i+f[j]]))) { // 小于等于 
						dp[i+f[j]] = s;
					}
				}
			}
		}
		
		if (dp[n] == tmp) {
			printf("-1\n");
		} else {
			cout << dp[n] << endl;
		}
	}
	
	return 0;
}

